insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_120'
from (values
('127.824.d.1.A',3,'A machinist glances at the corner of a print to learn the part name, the drawing scale, the material and the revision level before cutting any stock. That corner is the:','["title block", "bill of lading", "dimension line", "datum target"]'::jsonb,0,'The title block holds identifying data.','original'),
('127.824.d.1.A',4,'A print''s title block lists ''MATERIAL: 6061-T6'' and ''SCALE: 1:2''. The machinist learns that the part is:','["steel and drawn double size", "aluminum and drawn at half size", "plastic and drawn at half size", "brass and full size"]'::jsonb,1,'Scale 1:2 means half size.','original'),
('127.824.d.1.B',3,'A drawing shows the front, top and right-side views of a bracket, each aligned with the others. The reason a print uses several views is to:','["make the page look busy", "hide small details", "show all the features of the part from different directions", "avoid dimensions"]'::jsonb,2,'Multi-views describe shape.','original'),
('127.824.d.1.B',4,'A hole appears as a circle in the top view and as two dashed lines in the front view. Those dashed lines mean the hole:','["is a thread callout", "is missing", "is on the outside edge", "is hidden inside the part in that view"]'::jsonb,3,'Dashed lines show hidden features.','original'),
('127.824.d.1.C',3,'A drawing lists one length as 1.250 in., another as 1 1/4 in. and a third as 31.75 mm. The three forms are:','["decimal, fractional and metric dimensions", "only radial dimensions", "only angular dimensions", "only fractional dimensions"]'::jsonb,0,'Prints can use all three.','original'),
('127.824.d.1.C',4,'A part is dimensioned 25.4 mm. In inches that equals:','["0.254 in.", "1.000 in.", "2.54 in.", "10.0 in."]'::jsonb,1,'25.4 mm = 1 in.','original'),
('127.824.d.1.D',3,'A print has a cutting-plane line and a view that looks as if the part were sliced open to show internal walls and cavities. This is a:','["title view", "pictorial view", "section view", "reference view"]'::jsonb,2,'Section views reveal inside details.','original'),
('127.824.d.1.D',4,'The diagonal hatch lines in a section view mark:','["center lines", "dimension limits", "empty space", "the solid material cut by the cutting plane"]'::jsonb,3,'Hatching indicates cut material.','original'),
('127.824.d.1.E',3,'A drawing shows a box as one picture with its width, height and depth all drawn on 30-degree axes. This projection is:','["isometric", "orthographic", "schematic", "auxiliary"]'::jsonb,0,'Isometric uses 30-degree axes.','original'),
('127.824.d.1.E',4,'Which projection shows the front face true shape with the depth drawn on a single receding angle line?','["orthographic with three views", "oblique", "isometric", "schematic"]'::jsonb,1,'Oblique keeps the front face undistorted.','original'),
('127.824.d.1.F',3,'A bracket has a slanted face that looks foreshortened in the normal views. A print adds a view looking straight at that face to show its true size and shape. That is an:','["schematic view", "section view", "auxiliary view", "title view"]'::jsonb,2,'Auxiliary views show inclined surfaces true size.','original'),
('127.824.d.1.F',4,'An auxiliary view is drawn perpendicular to:','["the title block", "the border", "the bill of materials", "the inclined surface it describes"]'::jsonb,3,'Projection lines are perpendicular to the inclined surface.','original'),
('127.824.d.1.G',3,'A print gives the distance between two holes, the radius of a corner and the angle of a chamfer. These are:','["linear, radial and angular dimensions", "only title entries", "only ordinate dimensions", "only pictorial notes"]'::jsonb,0,'Dimension types differ by feature.','original'),
('127.824.d.1.G',4,'In ordinate dimensioning, every feature is dimensioned from:','["the nearest edge only", "a common zero or origin", "the title block", "the revision list"]'::jsonb,1,'Ordinate uses a datum origin.','original'),
('127.824.d.1.H',3,'A sales engineer sketches a part in a single three-dimensional picture to show how an assembly goes together on the shop floor. This pictorial drawing helps manufacturing by:','["replacing all dimensions", "hiding assembly steps", "showing the assembled appearance in one view", "listing prices"]'::jsonb,2,'Pictorials aid understanding.','original'),
('127.824.d.1.H',4,'An exploded pictorial drawing is most useful for:','["tolerance stack-up", "machine speeds", "payroll", "showing the order in which parts are assembled"]'::jsonb,3,'Exploded views show assembly order.','original'),
('127.824.d.1.I',3,'A print uses a feature control frame with symbols for flatness, position and datums to control the form and location of features. This is:','["geometric dimensioning and tolerancing", "only a title block", "a pictorial", "a schematic"]'::jsonb,0,'GD&T controls form and location.','original'),
('127.824.d.1.I',4,'A major purpose of GD&T in manufacturing is to:','["reduce print size only", "communicate the design''s functional requirements precisely", "remove all tolerances", "avoid inspection"]'::jsonb,1,'GD&T clarifies function.','original'),
('127.824.d.1.J',3,'A shaft is dimensioned 1.500 +0.002 / −0.001 in. The smallest acceptable diameter is:','["1.502 in.", "1.500 in.", "1.499 in.", "1.498 in."]'::jsonb,2,'1.500 − 0.001.','original'),
('127.824.d.1.J',4,'A hole is dimensioned 0.750 ± 0.005 in. A machinist measures 0.757 in. The hole is:','["within tolerance", "exactly nominal", "too small", "out of tolerance because it exceeds 0.755"]'::jsonb,3,'Upper limit is 0.755.','original'),
('127.824.d.1.K',3,'A print is marked scale 2:1. A feature measures 1 in. on the paper. On the actual part it is:','["0.5 in.", "1 in.", "2 in.", "4 in."]'::jsonb,0,'2:1 means the drawing is twice actual size.','original'),
('127.824.d.1.K',4,'If a drawing uses a 1:4 scale, a 12-in. part length would be drawn as:','["6 in.", "3 in.", "24 in.", "48 in."]'::jsonb,1,'12 ÷ 4 = 3.','original'),
('127.824.d.1.L',3,'One drawing shows what a hydraulic valve looks like on a machine. Another uses symbols and lines to show how the circuit is connected. The second is a:','["title block", "section view", "schematic drawing", "pictorial drawing"]'::jsonb,2,'Schematics use symbols.','original'),
('127.824.d.1.L',4,'A pictorial drawing differs from a schematic because a pictorial:','["is always an electrical circuit", "shows only symbols", "has no parts", "shows the actual appearance of the components"]'::jsonb,3,'Pictorial shows appearance.','original'),
('127.824.d.1.M',3,'On a print, a leader line points to a hole with the note ''Ø0.250 THRU, 4 PLACES''. This note is a:','["call out", "bill of materials", "revision block", "title entry"]'::jsonb,0,'Call outs describe features.','original'),
('127.824.d.1.M',4,'A call out that reads ''1/4-20 UNC-2B'' on a hole tells the machinist:','["the paint color", "the thread size and class to cut", "the shipping date", "the shop number"]'::jsonb,1,'Thread callouts give size and class.','original'),
('127.824.d.1.N',3,'A technician needs to trace how current flows to a motor, so she reads the drawing made of switch, relay and fuse symbols. That drawing is a(n):','["section view", "fluid power schematic", "electrical schematic", "piping drawing"]'::jsonb,2,'Electrical schematics show circuits.','original'),
('127.824.d.1.N',4,'A drawing showing a pump, cylinder and directional valve connected by lines is a:','["floor plan", "title block", "electrical schematic", "fluid power schematic"]'::jsonb,3,'Fluid power schematics show hydraulics and pneumatics.','original'),
('127.824.d.2.A',3,'To draw an arc with a 2-inch radius on a layout, the drafter sets the compass:','["with the point on the center and the pencil 2 in. away", "with a 4 in. opening", "with both ends on the line", "with the pencil on the center"]'::jsonb,0,'Compass radius equals the set distance.','original'),
('127.824.d.2.A',4,'A compass is used in technical drawing to make:','["arrowheads", "circles and arcs", "straight lines", "dashed lines"]'::jsonb,1,'Compasses draw circles and arcs.','original'),
('127.824.d.2.B',3,'To measure a shaft diameter to a thousandth of an inch, an inspector should use a:','["wooden ruler", "carpenter''s square", "micrometer", "tape measure"]'::jsonb,2,'Micrometers read thousandths.','original'),
('127.824.d.2.B',4,'A 6-inch steel scale is best used on a drawing or part to:','["read thousandths", "measure threads", "measure temperature", "read lengths to the nearest 1/64 or 1/32 inch"]'::jsonb,3,'Scales are for coarser measurements.','original'),
('127.824.d.2.C',3,'A student uses software to draw a part, add dimensions and view it from several angles on the screen before it is cut. This is:','["computer-aided design and drafting", "hand sketching only", "printing a form", "manual lettering"]'::jsonb,0,'CAD supports drawing and design.','original'),
('127.824.d.2.C',4,'A drafter must change a hole size on a part drawing that was made in design software. Compared with redrawing by hand, the software lets her:','["avoid any revision record", "edit the feature and update every view quickly", "erase the whole file", "start over on paper"]'::jsonb,1,'CAD edits propagate to all views.','original'),
('127.824.d.2,D',3,'A machinist sees a small box in a feature control frame holding the symbol for a circle with a cross, next to a number and a datum letter. That symbol set tells the machinist the part''s:','["price", "shipping date", "position tolerance for the feature", "paint color"]'::jsonb,2,'Position symbols control feature location.','original'),
('127.824.d.2,D',4,'On a blueprint, a symbol that looks like a stepped hole with a larger shallow diameter on top is the call out for a:','["chamfer", "thread", "weld", "counterbore"]'::jsonb,3,'Counterbore symbol.','original'),
('127.824.d.2.E',3,'A machinist sees one dimension on a print shown in parentheses. It is a reference dimension, which means it is:','["for information only and not used to check the part", "a required inspection size", "a driving dimension", "a tolerance zone"]'::jsonb,0,'Reference dimensions are informational.','original'),
('127.824.d.2.E',4,'A driving dimension on a print is one that:','["is always in parentheses", "controls the size or location and is toleranced", "is shown only for information", "has no tolerance"]'::jsonb,1,'Driving dimensions govern manufacturing.','original'),
('127.824.d.2.F',3,'On an electrical print, the symbol of a coil drawn with a circle labeled ''M'' usually stands for a:','["piping fitting", "bolt", "motor starter contactor", "gas valve"]'::jsonb,2,'Contactors and coils appear in control prints.','original'),
('127.824.d.2.F',4,'A symbol of a circle with a lamp marking in a control circuit represents a:','["fuse", "relay coil", "ground", "pilot lamp"]'::jsonb,3,'Lamp symbols indicate indicator lights.','original'),
('127.824.d.2.G',3,'On a fluid power print, the symbol for a pump or power unit shows:','["a circle with a triangle indicating flow direction", "a zigzag line", "a box with a plus sign", "a rectangle with no marks"]'::jsonb,0,'Pump symbols include a flow triangle.','original'),
('127.824.d.2.G',4,'A rectangle with an arrow inside and two or three connected squares in a hydraulic diagram is a:','["gauge", "directional control valve", "motor", "storage tank"]'::jsonb,1,'Directional valves use boxes.','original'),
('127.824.d.2.H',3,'On a piping and instrumentation diagram (P&ID), a circle with a letter ''P'' inside connected to a line usually represents a:','["tank", "switch", "pressure gauge or indicator", "valve actuator"]'::jsonb,2,'Instrument bubbles show measurements.','original'),
('127.824.d.2.H',4,'On a P&ID, a bow-tie shape on a pipe line represents:','["a filter", "a pump", "a gauge", "a valve"]'::jsonb,3,'Bow-tie is a gate valve symbol.','original'),
('127.824.d.2.I',3,'A print shows a symbol of a coil of wire as a zigzag or spiral to represent a:','["spring", "thread", "tank", "fastener"]'::jsonb,0,'Springs have standard symbols.','original'),
('127.824.d.2.I',4,'A drawing note reads ''M10 × 1.5''. This is a symbol for a:','["spring", "metric thread", "fastener head", "hole depth"]'::jsonb,1,'Metric thread notation.','original'),
('127.824.d.3.A',3,'A contractor reads a drawing that shows a building from above with walls, doors and room sizes. This is a:','["detail", "elevation", "floor plan", "section"]'::jsonb,2,'Floor plans show layout from above.','original'),
('127.824.d.3.A',4,'On a floor plan, a break in a wall with an arc drawn near it represents:','["a stair", "a drain", "a window", "a door and its swing"]'::jsonb,3,'Door swing arcs.','original'),
('127.824.d.3.B',3,'A drawing shows the front of a building as it would appear standing outside, with the height of the roof and windows. This is an:','["elevation drawing", "title block", "electrical schematic", "floor plan"]'::jsonb,0,'Elevations show exterior faces.','original'),
('127.824.d.3.B',4,'Elevation drawings are most useful for determining:','["pipe fittings", "heights and exterior appearance", "wiring sizes", "room color"]'::jsonb,1,'Elevations show vertical dimensions.','original'),
('127.824.d.3.C',3,'A drawing slices through a wall to show its framing, insulation and finish layers from inside to outside. This is a:','["schedule", "floor plan", "section view or detail", "site plan"]'::jsonb,2,'Sections show construction.','original'),
('127.824.d.3.C',4,'The best drawing for showing how a wall is built from layers is a:','["landscape plan", "site plan", "schedule", "wall section"]'::jsonb,3,'Wall sections show materials.','original'),
('127.824.d.3.D',3,'On a plan, a small circle with an ''S'' next to a wall usually represents:','["a light switch", "a smoke damper", "a stair", "a sink"]'::jsonb,0,'Electrical symbols.','original'),
('127.824.d.3.D',4,'A rectangle on a wall labeled ''DP'' on an electrical plan is the:','["drain pipe", "distribution panel", "door plan", "display panel for lights"]'::jsonb,1,'DP is a panel.','original'),
('127.824.d.3.E',3,'On a plumbing plan, a line showing where water enters the building and branches to fixtures is the:','["drain stack", "gas line", "water supply line", "vent only"]'::jsonb,2,'Supply lines carry water in.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_120'
from (values
('127.824.d.3.E',4,'A plumbing symbol for a floor drain looks like:','["a zigzag", "a triangle", "a square with an arrow", "a circle with a grid or X inside"]'::jsonb,3,'Floor drains use a grated circle.','original'),
('127.824.d.3.F',3,'On an HVAC drawing, a rectangle with an X inside on a ceiling usually represents a:','["supply air diffuser", "door", "water heater", "light"]'::jsonb,0,'Ceiling diffusers are marked with symbols.','original'),
('127.824.d.3.F',4,'The component on an HVAC plan that moves heated or cooled air through ducts is the:','["sink", "air handler or furnace", "distribution panel", "drain"]'::jsonb,1,'Air handlers move conditioned air.','original'),
('127.824.d.4.A',3,'A student sketches a slanted face of a bracket by projecting lines perpendicular to that face to show its true shape. She is sketching an:','["title block", "isometric view", "auxiliary projected view", "section"]'::jsonb,2,'Auxiliary views for inclined surfaces.','original'),
('127.824.d.4.A',4,'To show the true size of an inclined surface in a sketch, the student should draw the new view:','["with random lines", "with no lines", "with projection lines parallel to the surface", "with projection lines perpendicular to the inclined surface"]'::jsonb,3,'Perpendicular projection gives true shape.','original'),
('127.824.d.4.B',3,'A student draws front, top and right views of a small block, aligning them so features line up. She is creating a sketch using:','["multi-views", "only a schematic", "only a pictorial", "only a symbol"]'::jsonb,0,'Multi-view sketching.','original'),
('127.824.d.4.B',4,'In a three-view sketch, the top view is placed:','["below the right view", "directly above the front view", "anywhere", "to the left of the front view"]'::jsonb,1,'Standard layout.','original'),
('127.824.d.4.C',3,'A student adds size dimensions, extension lines, dimension lines and arrowheads to each view of a multi-view sketch. She is:','["hiding the views", "coloring the views", "annotating the views with proper dimensioning standards", "erasing views"]'::jsonb,2,'Dimensions are annotated by standard.','original'),
('127.824.d.4.C',4,'A standard practice for dimensions on a drawing is to:','["omit all sizes", "place all sizes inside the part", "repeat every size three times", "avoid repeating the same dimension in multiple views"]'::jsonb,3,'Don''t duplicate dimensions.','original'),
('127.824.d.5.A',3,'A hole is dimensioned 0.500 ± 0.003 in. This is a bilateral tolerance because the allowed variation:','["goes both above and below the nominal size", "goes only below", "is zero", "goes only above"]'::jsonb,0,'Bilateral tolerances vary both ways.','original'),
('127.824.d.5.A',4,'A shaft is dimensioned 1.000 +0.000 / −0.004 in. This tolerance is:','["unknown", "unilateral because the variation goes only one direction", "bilateral", "zero"]'::jsonb,1,'Unilateral goes one way.','original'),
('127.824.d.5.B',3,'A shaft''s largest allowed size is 0.998 in. and a hole''s smallest allowed size is 1.000 in. The tightest clearance when mating is:','["0.000 in.", "0.020 in.", "0.002 in.", "0.200 in."]'::jsonb,2,'1.000 − 0.998.','original'),
('127.824.d.5.B',4,'A shaft has limits 0.998 to 0.996 in. and a hole has limits 1.002 to 1.000 in. The maximum possible clearance is:','["0.008 in.", "0.002 in.", "0.004 in.", "0.006 in."]'::jsonb,3,'1.002 − 0.996.','original'),
('127.824.d.6.A',3,'A drafting department has a standard block that lists revision letters, dates and who approved each change. This standard practice is a:','["revision history in the title area", "blueprint paper", "lettering style", "scale bar"]'::jsonb,0,'Revision tables track changes.','original'),
('127.824.d.6.A',4,'The purpose of a revision history on a print is to:','["count parts", "track what changed, when and why", "hide changes", "list tool names"]'::jsonb,1,'Revisions document changes.','original'),
('127.824.d.6.B',3,'An engineer needs to change a hole size on a print. To keep it accurate, she should update the drawing and:','["leave the old copy in use", "erase the note", "update the revision block and notify affected users", "hide the change"]'::jsonb,2,'Control changes.','original'),
('127.824.d.6.B',4,'If a drawing is revised but the old print stays on the shop floor, the shop may:','["build it correctly", "save time safely", "avoid scrap", "build the part to the wrong size"]'::jsonb,3,'Obsolete prints cause errors.','original'),
('127.824.d.6.C',3,'A revision entry should include the date, a description of the change and:','["the approval or initials of the person who made it", "the weather", "the lunch menu", "the machine color"]'::jsonb,0,'Revision entries are signed.','original'),
('127.824.d.6.C',4,'Which is a correctly written revision entry?','["Updated stuff", "Rev B – 03/12/2026 – Hole increased from 0.250 to 0.281 – J. Lee", "Fixed", "Rev B changed"]'::jsonb,1,'Entries are specific.','original'),
('127.828.d.1.A',3,'Rafael walks past a conveyor and hears a rhythmic squeal, feels extra vibration in the frame and sees a trace of oil under the motor. He is identifying a malfunction using:','["a lab test only", "guessing from the price", "visual, audible and other sensory inspection", "a computer printout only"]'::jsonb,2,'Eyes, ears and touch catch early problems.','original'),
('127.828.d.1.A',4,'A technician smells hot insulation near a motor starter panel. The best first response is to:','["spray water on the panel", "ignore it until the shift ends", "keep the machine running", "stop the equipment safely and report the odor"]'::jsonb,3,'Burning odors indicate overheating.','original'),
('127.828.d.1.B',3,'A press is moved by an oil pump, a cylinder and a control valve. This machine is mainly a:','["hydraulic system", "pneumatic system", "electrical system only", "hand-powered system"]'::jsonb,0,'Oil under pressure is hydraulic.','original'),
('127.828.d.1.B',4,'Compared with a hydraulic system, a pneumatic system uses:','["oil as its working fluid", "compressed air as its working fluid", "water only", "gears only"]'::jsonb,1,'Pneumatic = air.','original'),
('127.828.d.1.C',3,'Before servicing a belt-driven fan, Mia notes that the rotating shaft and pulley can catch loose sleeves and hair. This is a safety concern from:','["paint fumes only", "static charge only", "rotating equipment", "noise only"]'::jsonb,2,'Rotating parts can entangle.','original'),
('127.828.d.1.C',4,'Which practice reduces the danger of rotating equipment during maintenance?','["wear loose jewelry", "work while it spins", "remove the guards and run it", "lock out the machine and secure loose clothing and hair"]'::jsonb,3,'Control energy and avoid entanglement.','original'),
('127.828.d.1.D',3,'A training instructor writes steps for students to service a drill press: lock out power, gather tools, wear eye protection and verify zero energy. This is a:','["safe plan of action for an industrial training setting", "sales plan", "random list", "price list"]'::jsonb,0,'A safe plan lists steps in order.','original'),
('127.828.d.1.D',4,'A safe plan for a new maintenance training lab should be:','["optional for visitors", "written, reviewed and followed by every student", "unwritten", "skipped when busy"]'::jsonb,1,'Plans only work when followed.','original'),
('127.828.d.1.E',3,'To remove old paint and rust from a metal bracket before repair, a technician would choose a:','["paint roller", "ruler", "wire brush or abrasive pad", "level"]'::jsonb,2,'Cleaning uses abrasives and brushes.','original'),
('127.828.d.1.E',4,'Which tool would a technician use to cut a short section of steel pipe in the shop?','["a screw gun", "a spirit level", "a tape measure only", "a pipe cutter or hacksaw"]'::jsonb,3,'Cutting tools suit the task.','original'),
('127.828.d.1.F',3,'When using an abrasive cut-off saw, the operator should always:','["wear eye and face protection and keep guards in place", "remove the guard", "wear loose gloves near the blade", "hold the work by hand without clamping"]'::jsonb,0,'Guards and PPE protect.','original'),
('127.828.d.1.F',4,'A drill bit grabs and spins the workpiece. The most likely cause is that the part was:','["painted", "not clamped securely", "too short", "too clean"]'::jsonb,1,'Clamp the work.','original'),
('127.828.d.1.G',3,'To check a shaft diameter to 0.001 in., the technician selects a:','["yardstick", "wood ruler", "micrometer", "tape measure"]'::jsonb,2,'Micrometers read thousandths.','original'),
('127.828.d.1.G',4,'A dial caliper is able to measure all of the following EXCEPT:','["outside diameter", "inside diameter", "depth", "internal volume of a tank"]'::jsonb,3,'Calipers measure length features.','original'),
('127.828.d.1.H',3,'A technician replaces a bolt on a heavily loaded press with one of a lower grade. The risk is that the fastener may:','["fail under load", "tighten itself", "last longer", "change color"]'::jsonb,0,'Strength grade matters.','original'),
('127.828.d.1.H',4,'Hardened steel fasteners are chosen over soft aluminum ones when the joint must carry:','["only a label", "high loads", "no load", "only decoration"]'::jsonb,1,'Material strength matches the load.','original'),
('127.828.d.2.A',3,'A technician writes a one-page maintenance plan listing the equipment, the task, the interval and the parts needed. This is an example of:','["a bank statement", "a menu", "technical communication", "a travel plan"]'::jsonb,2,'Plans communicate work to others.','original'),
('127.828.d.2.A',4,'When explaining a machine problem to a supervisor, the technician should:','["exaggerate", "avoid details", "use vague words", "use specific observations and measurements"]'::jsonb,3,'Be precise.','original'),
('127.828.d.2.B',3,'Each time the oil on a gearbox is changed, a technician initials a sheet that stays with the machine. The sheet is a:','["maintenance logbook entry", "pay stub", "calendar of holidays", "menu"]'::jsonb,0,'Logbooks record work done.','original'),
('127.828.d.2.B',4,'A checklist for a daily equipment inspection helps a technician to:','["guess results", "make sure no inspection items are missed", "avoid inspections", "skip documentation"]'::jsonb,1,'Checklists improve consistency.','original'),
('127.828.d.2.C',3,'A technician schedules a monthly plan to grease the bearings on three motors, with the grease type, amount and who will do it. This is:','["closing the shop", "buying lunch", "developing and executing a plan for a maintenance task", "painting walls"]'::jsonb,2,'Plan the task, then do it.','original'),
('127.828.d.2.C',4,'When lubricating a bearing, over-greasing can:','["lower friction forever", "remove the need for checks", "never matter", "overheat the bearing or blow the seals"]'::jsonb,3,'Too much grease is harmful.','original'),
('127.828.d.3.A',3,'A shop supervisor leads a repair project by defining the goal, planning the steps, doing the work, checking progress and closing it out. These stages are:','["initiating, planning, executing, monitoring and closing", "starting, quitting, resting", "painting, drying, packing", "buying, selling, trading"]'::jsonb,0,'Project phases.','original'),
('127.828.d.3.A',4,'The stage of a project in which the team confirms the repair meets the requirements and finishes the paperwork is:','["guessing", "closing", "initiating", "planning only"]'::jsonb,1,'Closing wraps up.','original'),
('127.828.d.3.B',3,'To repair a damaged bracket, a technician drills out a broken screw, taps new threads and installs a larger screw. These are:','["selling steps", "painting steps", "maintenance repair processes using appropriate tools", "packing steps"]'::jsonb,2,'Repair uses tools and processes.','original'),
('127.828.d.3.B',4,'Before drilling a hole in a part, the technician should:','["hold the part in a hand", "use a dull bit", "skip layout", "mark the center with a punch so the bit does not wander"]'::jsonb,3,'Center punch guides the bit.','original'),
('127.828.d.3.C',3,'A hex nut on a pipe flange is tight in a cramped spot. For the best grip on all six sides of the nut, the technician should use a:','["box end wrench", "hammer", "pair of pliers", "open end wrench only"]'::jsonb,0,'Box wrenches grip all sides.','original'),
('127.828.d.3.C',4,'A technician needs to remove an oil filter that has no flat surfaces to grip. The tool for the job is a:','["hex key", "filter wrench", "torque wrench", "feeler gauge"]'::jsonb,1,'Filter wrenches grip round cases.','original'),
('127.828.d.4.A',3,'Under the Occupational Safety and Health Act, an employer must provide a workplace free of recognized hazards and a worker must:','["skip training", "remove guards", "follow safety rules and use required PPE", "ignore safety rules"]'::jsonb,2,'Both parties have duties.','original'),
('127.828.d.4.A',4,'Which is a responsibility of the employer for workplace safety?','["charge for PPE in all cases", "avoid training", "remove warning signs", "provide training and required protective equipment"]'::jsonb,3,'Employers must provide safe conditions.','original'),
('127.828.d.4.B',3,'OSHA standards matter in a shop because they:','["set minimum requirements to protect workers from hazards", "set the pay rates", "approve company logos", "decide the price of products"]'::jsonb,0,'OSHA sets safety standards.','original'),
('127.828.d.4.B',4,'A worker who reports a hazard to OSHA is protected from:','["paying taxes", "retaliation by the employer", "all training", "all inspections"]'::jsonb,1,'Workers have rights.','original'),
('127.828.d.4.C',3,'An OSHA compliance officer arrives at a plant, shows credentials, holds an opening conference, walks through the workplace and holds a closing conference. This describes how:','["a sales call is made", "an audit of payroll is run", "an OSHA inspection is conducted", "a fire drill is run"]'::jsonb,2,'Inspections follow a process.','original'),
('127.828.d.4.C',4,'After an OSHA inspection finds violations, the employer typically receives:','["no notice", "a trophy", "a gift", "a citation and a deadline to correct the hazards"]'::jsonb,3,'Citations specify abatement dates.','original'),
('127.828.d.4.D',3,'A state agency and a national agency both work to enforce workplace safety rules. The national agency that sets most workplace safety standards is:','["OSHA", "the FAA", "the post office", "the IRS"]'::jsonb,0,'OSHA is the federal safety agency.','original'),
('127.828.d.4.D',4,'NIOSH''s role in workplace safety is mainly to:','["issue citations", "research hazards and recommend ways to prevent injuries", "set pay rates", "collect taxes"]'::jsonb,1,'NIOSH conducts research.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_120'
from (values
('127.828.d.4.E',3,'Excessive noise, dust that irritates the lungs, mold and repetitive lifting are all examples of:','["payroll hazards", "marketing hazards", "industrial hygiene hazards", "parking hazards"]'::jsonb,2,'Physical, chemical, biological and ergonomic.','original'),
('127.828.d.4.E',4,'Lifting heavy parts repeatedly with poor posture is mainly an:','["biological hazard", "chemical hazard", "radiation hazard", "ergonomic hazard"]'::jsonb,3,'Ergonomics concerns body strain.','original'),
('127.828.d.4.F',3,'A maintenance team wipes up an oil spill, covers cords in a walkway and puts railings on a platform. These actions support:','["safe walking and working surfaces", "tool sales", "paint selection", "machine speed"]'::jsonb,0,'Surface safety prevents falls.','original'),
('127.828.d.4.F',4,'The most common cause of injuries on walking surfaces is:','["noise", "slips, trips and falls", "radiation", "laser exposure"]'::jsonb,1,'Slips, trips and falls.','original'),
('127.828.d.4.G',3,'Exposed wiring, overloaded outlets and damaged cords are examples of:','["noise hazards", "ergonomic hazards", "electrical hazards in the workplace", "biological hazards"]'::jsonb,2,'Electrical hazards cause shock and fire.','original'),
('127.828.d.4.G',4,'A worker touching a live conductor can receive:','["no effect", "a free meal", "only a sound", "an electric shock or burn"]'::jsonb,3,'Contact causes shock.','original'),
('127.828.d.4.H',3,'Plugging power tools into a ground-fault circuit interrupter outlet and replacing frayed cords are:','["control methods to prevent electrical hazards", "scheduling aids", "decorating ideas", "advertising tips"]'::jsonb,0,'GFCIs and repairs prevent shock.','original'),
('127.828.d.4.H',4,'A key control method for electrical hazards is:','["working on live panels", "lockout/tagout before servicing equipment", "removing grounds", "ignoring labels"]'::jsonb,1,'De-energize first.','original'),
('127.828.d.4.I',3,'A worker stores solvent cans near an ignition source and transports them without secure lids. This shows a hazard in:','["scheduling", "marketing", "handling and storing hazardous materials", "painting"]'::jsonb,2,'Improper handling is dangerous.','original'),
('127.828.d.4.I',4,'Hazardous materials should be transported in:','["unlabeled bottles", "open buckets", "pockets", "approved, closed and labeled containers"]'::jsonb,3,'Containers must be approved.','original'),
('127.828.d.4.J',3,'A shop installs local exhaust ventilation at the solvent tank and requires gloves and goggles when handling it. These steps:','["reduce exposure to hazardous materials", "ignore the hazard", "increase exposure", "remove the tank"]'::jsonb,0,'Engineering and PPE reduce exposure.','original'),
('127.828.d.4.J',4,'Substituting a less hazardous cleaning product for a more toxic one is a way to:','["avoid training", "reduce exposure at the source", "increase risk", "hide hazards"]'::jsonb,1,'Substitution reduces hazard.','original'),
('127.828.d.4.K',3,'A new technician looks at the posted emergency plan, the eyewash station map and the safety data sheet binder. These are:','["sales tools", "decorations", "workplace health and safety resources", "pay resources"]'::jsonb,2,'Know where resources are.','original'),
('127.828.d.4.K',4,'Where can a technician find information about the hazards of a specific chemical?','["the time clock", "the shipping schedule", "the break room menu", "the safety data sheet"]'::jsonb,3,'SDS covers hazards.','original'),
('127.828.d.4.L',3,'A company has a written safety and health program with management commitment, worker participation and hazard identification. These are:','["elements of a safety and health program", "tools of marketing", "pieces of a menu", "parts of a sales plan"]'::jsonb,0,'Program elements.','original'),
('127.828.d.4.L',4,'A safety and health program works best when management:','["ignores reports", "shows leadership and involves workers", "blames workers", "avoids safety talks"]'::jsonb,1,'Leadership is key.','original'),
('127.828.d.4.M',3,'A plant keeps a written plan that explains what workers should do if a fire breaks out, how to report it and who is in charge. This is an:','["inventory sheet", "menu plan", "emergency action and fire protection plan", "pay chart"]'::jsonb,2,'Written plans guide emergencies.','original'),
('127.828.d.4.M',4,'A written emergency action plan must include:','["a holiday schedule", "a staff party menu", "the price of equipment", "how to report emergencies and how to evacuate"]'::jsonb,3,'Plans include reporting and evacuation.','original'),
('127.828.d.4.N',3,'A building posts a map showing marked exits, a meeting place outside and the location of extinguishers. These are:','["key components of an evacuation plan", "elements of a menu", "parts of a pay chart", "pieces of a sales brochure"]'::jsonb,0,'Routes and assembly points.','original'),
('127.828.d.4.N',4,'An emergency exit route must be:','["locked at all times", "kept clear and unlocked during working hours", "hidden", "blocked with boxes"]'::jsonb,1,'Exits stay clear.','original'),
('127.828.d.4.O',3,'A plant has trained workers who serve as first responders, fire wardens and the person who calls emergency services. These are:','["marketing staff", "visitors", "emergency personnel within an organization", "payroll staff"]'::jsonb,2,'Roles in emergencies.','original'),
('127.828.d.4.O',4,'A fire warden''s job during an evacuation is to:','["lock the exits", "collect pay", "start the machines", "help ensure everyone leaves and is accounted for"]'::jsonb,3,'Wardens help with evacuation.','original'),
('127.828.d.4.P',3,'A shop labels chemical containers, keeps safety data sheets handy and trains workers on chemical hazards. These are parts of a:','["hazard communication program", "sales program", "pricing program", "travel program"]'::jsonb,0,'HazCom includes labels, SDS and training.','original'),
('127.828.d.4.P',4,'Under the hazard communication standard, a container of a hazardous chemical must have a:','["blank cover", "label identifying the product and its hazards", "company song", "price tag only"]'::jsonb,1,'Labels communicate hazards.','original'),
('127.828.d.4.Q',3,'OSHA requires that employees get training on hazards they may face, such as lockout/tagout and hazard communication. This is an example of:','["vacation policies", "parking rules", "safety and health training requirements", "pay requirements"]'::jsonb,2,'OSHA specifies training.','original'),
('127.828.d.4.Q',4,'Training on a new chemical should happen:','["never", "after an injury", "after retirement", "before workers are exposed to it"]'::jsonb,3,'Train before exposure.','original'),
('127.828.d.5.A',3,'Used oil, spent solvent and oily rags are sorted into labeled containers and stored in a closed cabinet until a licensed hauler picks them up. This is:','["proper storage and disposal of hazardous materials", "burning waste", "careless disposal", "dumping waste"]'::jsonb,0,'Store labeled, dispose properly.','original'),
('127.828.d.5.A',4,'A technician has a half-full can of gasoline left from cleaning parts. Where should it be kept until it is properly disposed of?','["in the break room", "in a closed, approved flammable-liquid cabinet", "on an open shelf by the grinder", "in a plastic grocery bag"]'::jsonb,1,'Flammable storage rules.','original'),
('127.828.d.5.B',3,'For a maintenance task involving chemical splashes and flying chips, a technician puts on gloves, goggles and a face shield. These are:','["machine parts", "office supplies", "personal protective equipment", "tool storage"]'::jsonb,2,'PPE protects workers.','original'),
('127.828.d.5.B',4,'PPE should be selected based on:','["the coworker''s taste", "the cost alone", "the color options", "the hazards of the task"]'::jsonb,3,'Hazard assessment.','original'),
('127.828.d.5.C',3,'Before changing a belt on a conveyor, Dana turns off the main disconnect, puts on her lock and tag and tries the start button to verify the machine will not run. She is performing:','["lockout/tagout", "a lube job", "a cleaning only", "a break"]'::jsonb,0,'Lockout/tagout controls energy.','original'),
('127.828.d.5.C',4,'Who may remove a lockout lock after servicing is complete?','["any worker", "the person who applied it", "the supervisor only without checking", "the next shift automatically"]'::jsonb,1,'Each worker uses their own lock.','original'),
('127.828.d.5.D',3,'Before using a portable circular saw, a technician checks the guard, sets the depth and clamps the work. This is:','["a cleanup", "a repair", "safe operation of a power tool", "a break"]'::jsonb,2,'Safe power tool use.','original'),
('127.828.d.5.D',4,'A drill press operator should never:','["secure loose hair", "wear eye protection", "clamp the work", "hold small parts by hand while drilling"]'::jsonb,3,'Hand-holding small parts is unsafe.','original'),
('127.828.d.5.E',3,'For grinding a metal weld, the technician chooses safety glasses, a face shield, hearing protection and gloves. This is selecting:','["appropriate PPE for operating a power tool", "party wear", "office clothing", "sports gear"]'::jsonb,0,'Power tool PPE.','original'),
('127.828.d.5.E',4,'For an angle grinder, the best combination of PPE includes:','["a hat only", "a face shield over safety glasses and hearing protection", "sunglasses only", "no PPE"]'::jsonb,1,'Flying debris and noise.','original'),
('127.828.d.6.A',3,'Every month a technician greases the bearings on a fan, cleans a filter and inspects belts before anything breaks. This is:','["breakdown repair", "a demolition", "preventative maintenance", "a sales call"]'::jsonb,2,'PM keeps equipment running.','original'),
('127.828.d.6.A',4,'The main goal of preventative maintenance is to:','["remove all inspections", "wait for failures", "increase downtime", "prevent failures before they happen"]'::jsonb,3,'Prevent failures.','original'),
('127.828.d.6.B',3,'A maintenance team reviews records showing a pump seal fails about every 90 days and decides to replace it every 75 days. They are setting a PM schedule based on:','["data from machine breakdowns", "guesswork", "the weather", "calendar holidays"]'::jsonb,0,'Use data to schedule PM.','original'),
('127.828.d.6.B',4,'If a bearing fails every 6 months on average, a reasonable PM interval to replace it would be:','["every 12 months", "about every 5 months", "never", "every 3 years"]'::jsonb,1,'Replace before failure.','original'),
('127.828.d.6.C',3,'Fixing a motor after it burns out is:','["preventative maintenance", "project management", "reactive maintenance", "predictive maintenance"]'::jsonb,2,'Reactive = after failure.','original'),
('127.828.d.6.C',4,'Using vibration readings to decide when a bearing will fail and replacing it just before is:','["reactive maintenance", "ordinary cleaning", "preventative only", "predictive maintenance"]'::jsonb,3,'Predictive uses condition data.','original'),
('127.828.d.7.A',3,'A student learns that students can become maintenance technicians, machinists, welders or CNC operators. These are:','["special skill career pathways in manufacturing", "retail jobs", "restaurant jobs", "teaching jobs only"]'::jsonb,0,'Career pathways.','original'),
('127.828.d.7.A',4,'A career pathway that focuses on keeping machines running in a factory is:','["sales clerk", "maintenance technician", "museum guide", "cook"]'::jsonb,1,'Maintenance techs keep equipment running.','original'),
('127.828.d.7.B',3,'A student joins a regional manufacturers'' association and attends a career fair to meet professionals and learn about job openings. This shows the value of:','["staying isolated", "only studying alone", "industry networking opportunities", "avoiding contacts"]'::jsonb,2,'Networking opens doors.','original'),
('127.828.d.7.B',4,'Joining a professional organization like the Society of Manufacturing Engineers can help a worker:','["lose contacts", "reduce skills", "avoid learning", "meet professionals and learn about opportunities"]'::jsonb,3,'Organizations connect people.','original'),
('127.828.d.7.C',3,'In a plant, one person designs a new part, another sets up and programs the equipment, and another operates and maintains the machine. These are the roles of:','["engineers, technologists and technicians", "only customers", "only salespeople", "only managers"]'::jsonb,0,'Different roles in manufacturing.','original'),
('127.828.d.7.C',4,'Which role typically involves designing products and processes using advanced math and science?','["driver", "engineer", "painter only", "cashier"]'::jsonb,1,'Engineers design.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
